import {B,P,G,GC} from './business.js';
const SITE_BASE=new URL('.',import.meta.url).pathname;
const asset=path=>new URL(path.replace(/^\/+/,''),import.meta.url).href;
const F=[['Pony rides',21,'Pony rides are listed on supplied posters. The photo shows a person beside a pony; confirm which experiences are offered and what participation is permitted.'],['Pony feeding',5,'A photograph shows horses eating hay. Ask whether guests may take part in any animal activity; the photograph alone does not confirm this.'],['Family horse experience',23,'A family is pictured beside a horse in a paddock. Ask the venue which animal experiences, if any, are available.'],['Petting zoo',4,'Petting zoo access appears on all five package posters. The supplied animal photographs show parts of the outdoor enclosure; confirm which animals and experiences are available.'],['Geese',6,'Geese are pictured in an outdoor enclosure. Confirm whether guests can visit and any supervision requirements.'],['Chickens',14,'The supplied photograph shows chickens beside their coop. Ask about access and supervision.'],['Paddock & pond',13,'Photographs show the paddock and a pond on the grounds. Ask about access and safety arrangements.'],['Play area',8,'The supplied photograph shows swings and an inflatable castle. Confirm what is available for your date.'],['Swings & slide',12,'A photograph shows swings and a slide beneath the trees. Ask about access and supervision.'],['Pony grooming station',22,'A poster advertises a pony grooming station. This photo shows grooming supplies and carrots; confirm whether the activity is available and what guests may do.'],['Jungle gym',null,'Jungle gym access appears on each supplied package poster. Confirm the current facility and inclusion.'],['Jumping castle',null,'Advertised in Silver, Gold, Platinum and Ultimate poster references. Confirm availability for your date.'],['Stretch tent',null,'Advertised on the Platinum and Ultimate posters. Confirm whether it is available and included.'],['Balloon house',null,'Advertised on the Platinum and Ultimate posters. Confirm details before booking.'],['Themed ceramic painting',null,'Advertised on the Platinum and Ultimate posters. Confirm theme, materials and inclusion.'],['Party seating & basic setup',9,'The posters refer to seating and basic setup. Photographs show different styled arrangements; ask what is included.'],['Buffet serving area',10,'A photograph shows a buffet table. Ask what food or serving arrangements are available; the photograph does not confirm package inclusions.'],['Sweet table',19,'A photograph shows sweets arranged on a table. Confirm whether treats or styling are available for your booking.'],['Party favours',16,'A photograph shows party favour boxes. Confirm whether favours are available for your booking.'],['Table details',11,'A close-up of napkin, glassware and table styling. Ask what tableware is included.'],['Parking',null,'Parking is advertised in each supplied package reference. Confirm current arrangements with the venue.']];
const A=(path,text,cls='')=>`<a href="${SITE_BASE}${path.replace(/^\//,'')}" class="${cls}" data-route>${text}</a>`, im=(i,cls='')=>`<img class="${cls}" src="${asset('public/images/'+G[i][0])}" alt="${G[i][1]}" loading="${i===0?'eager':'lazy'}" decoding="async">`, eye=t=>`<div class="eyebrow"><i></i>${t}<i></i></div>`, btn=(path,text)=>A(path,`${text}<b>↗</b>`,'button'), cta=()=>`<section class="cta"><div>${eye('Make room for the good stuff')}<h2>Let’s plan their<br><em>special day.</em></h2></div>${btn('/contact','Enquire about a party')}</section>`;
const nav=[['/','Home'],['/venue','The Venue'],['/experiences','Experiences'],['/packages','Packages'],['/gallery','Gallery'],['/contact','Contact']];
function header(){return `<header class="header"><a class="brand" href="${SITE_BASE}" data-route aria-label="Sister & Co. home"><img src="${asset(B.logo)}" alt="Sister & Co. floral logo"></a><button class="menu" aria-label="Open navigation" aria-expanded="false">☰</button><nav>${nav.map(([url,label])=>A(url,label)).join('')}${btn('/contact','Enquire about a party')}</nav></header>`}
function footer(){return `<footer class="footer"><div class="foot"><a href="${SITE_BASE}" data-route><img src="${asset(B.logo)}" alt="Sister & Co."></a><p>Little celebrations.<br><em>Big memories.</em></p><div class="footnav">${nav.map(([u,l])=>A(u,l)).join('')}</div><div class="footinfo"><a href="tel:0710648880">${B.phone}</a><span>${B.address}</span><a href="${B.facebook}" target="_blank" rel="noreferrer">Visit our Facebook ↗</a></div></div><div class="footbottom">© ${new Date().getFullYear()} Sister & Co. Party Venue <span>Contact and location details awaiting owner confirmation.</span></div></footer>`}
function pageHero(k,title,copy,img=''){return `<section class="pagehero">${eye(k)}<h1>${title}</h1><p>${copy}</p>${img?im(img):''}</section>`}
function home(){return `<main><section class="hero"><div>${eye('Hartzenbergfontein · Party venue')}<h1>Little celebrations.<br><em>Big memories.</em></h1><p>A welcoming place for children’s birthdays and special occasions, with a farm-style setting and party experiences to explore.</p><div class="actions">${btn('/packages','Explore our packages')}${A('/contact','Enquire about a party →','textlink')}</div><div class="script">A day made for being together</div></div><div class="heroimg">${im(0)}<span>A glimpse of a celebration at Sister & Co.</span></div></section><section class="welcome"><div>${im(1)}<small>01 / A PLACE TO GATHER</small></div><article>${eye('A setting for celebrating')}<h2>Room for joy,<br><em>made your own.</em></h2><p>From a dressed party table to a cheerful room full of colour, the supplied photographs show a venue that can be styled for a special day. Ask us which setup and activities are available for your date.</p>${A('/venue','Get to know the venue →','textlink')}<div class="script">with love, always</div></article></section><section class="outdoors"><div class="sectionhead">${eye('Outdoors, indoors & in between')}<h2>Little adventures<br>are part of the <em>story.</em></h2><p>Explore the experiences advertised by the venue. Availability and package inclusions should be confirmed when enquiring.</p>${A('/experiences','Discover experiences →','textlink')}</div><div class="tiles">${[3,4,2].map((n,i)=>A('/experiences',`${im(n)}<span>${['Pony experiences','A farm-style setting','Party details'][i]} ↗</span>`,'tile t'+i).replaceAll('>','>')).join('')}</div></section><section class="packagepreview"><div class="sectionhead center">${eye('Find your kind of celebration')}<h2>Five ways to <em>celebrate.</em></h2><p>Packages as advertised on supplied posters. Inclusions and prices await owner confirmation.</p></div><div class="packageindex">${P.map((p,i)=>A('/packages',`<i>0${i+1}</i><strong>${p[0]}<small>Package · Enquire for pricing</small></strong><b>↗</b>`)).join('')}</div></section><section class="tease"><div>${eye('Real moments, real place')}<h2>A peek at <em>the venue.</em></h2><p>Browse the rooms, table details and a little of the outdoors.</p>${A('/gallery','See the gallery →','textlink')}</div><div>${im(17)}${im(9)}${im(8)}</div></section><section class="teamfeature">${im(24)}<article>${eye('The people behind the parties')}<h2>Meet the <em>Sister & Co. team.</em></h2><p>Get to know the team in this photograph. Contact the venue to discuss your celebration and booking details.</p>${A('/contact','Get in touch →','textlink')}</article></section>${cta()}</main>`}
function venue(){return `<main>${pageHero('A place to gather','The Venue','A bright party room, thoughtful table details and serving areas—see the real spaces in the photographs and ask about the setup for your celebration.',0)}<section class="story"><article>${eye('Inside the celebration')}<h2>A room with space<br>for <em>your kind of day.</em></h2><p>The indoor party room has been photographed dressed for a children’s celebration, with a long low table, floor cushions and a balloon backdrop. Setups shown are examples; ask which arrangement is available for your booking.</p></article>${im(0)}</section><section class="story reverse">${im(1)}<article>${eye('Set the table')}<h2>Little details,<br><em>lovingly arranged.</em></h2><p>One supplied photograph shows a styled table with place settings, white linens and a green runner. Confirm the setup and any included tableware with the venue.</p></article></section><section class="station">${im(2)}<article>${eye('Serving station')}<h2>Refreshments<br><em>within reach.</em></h2><p>A wooden drinks cabinet and serving area appears in the supplied photograph. Ask about what is provided as part of your chosen package.</p></article></section><section class="story reverse">${im(10)}<article>${eye('Food and serving')}<h2>A place to serve<br><em>your party food.</em></h2><p>The photograph shows a buffet table and serving equipment. Ask the venue what, if anything, is available for your booking; this image does not confirm food or catering inclusions.</p></article></section><section class="venuephotos"><div class="sectionhead">${eye('Table styling')}<h2>Details for <em>celebrating.</em></h2><p>Examples of indoor table arrangements and party touches shown in the supplied photographs.</p></div><div class="venuephotogrid">${[9,11,16,15,19,20,17,18].map(i=>`<figure>${im(i)}<figcaption>${G[i][2]}</figcaption></figure>`).join('')}</div><div class="sectionhead venue-subhead">${eye('Outdoors & farm grounds')}<h2>Room to <em>explore.</em></h2><p>See the outdoor grounds and animals. Ask which areas are open to guests and what activities are currently available.</p></div><div class="venuephotogrid">${[3,4,5,6,7,13,14,8,12,21,23].map(i=>`<figure>${im(i)}<figcaption>${G[i][2]}</figcaption></figure>`).join('')}</div><p class="note">Animal photographs show the grounds and pictured moments. They do not confirm that guests may feed, handle or ride an animal.</p><p class="gallery-link">${A('/gallery','See all venue photographs →','textlink')}</p></section>${cta()}</main>`}
function experiences(){return `<main>${pageHero('Play, explore, celebrate','Experiences & Facilities','The supplied promotional material advertises a mix of indoor setup, outdoor play and animal experiences. Each package determines what is included; availability should be confirmed for your date.') }<section class="facilities">${F.map(([name,photo,copy],i)=>`<article>${photo!==null?im(photo):`<div class="art"><small>0${i+1}</small><i>✳</i></div>`}<div><small>ADVERTISED EXPERIENCE</small><h2>${name}</h2><p>${copy}</p></div></article>`).join('')}</section><aside class="notice"><b>Before you book</b><p>These facilities are based on supplied poster references. The current offering and package-specific inclusions have not yet been owner-verified.</p>${A('/contact','Ask about your date →','textlink')}</aside>${cta()}</main>`}
function packages(){return `<main>${pageHero('Choose your celebration','Party Packages','Explore the five packages advertised in the supplied posters. Inclusions below are a preliminary transcription, and every price is available by enquiry.') }<section class="packages">${P.map((p,i)=>`<article class="package" id="${p[0].toLowerCase()}"><div class="poster"><img src="${asset('public/images/'+p[1])}" alt="${p[0]} Package promotional poster reference" loading="lazy"><small>POSTER REFERENCE · 0${i+1}</small></div><div>${eye('Poster reference — awaiting owner verification')}<h2>${p[0]}<em> Package</em></h2><p>${p[2]}</p><div class="price">Enquire for pricing</div><h3>Advertised inclusions</h3><ul>${p[3].map(s=>`<li>✳ ${s}</li>`).join('')}</ul><p class="note">Poster references show differences in presentation. Confirm final details, availability and price with the venue before booking.</p>${btn('/contact?package='+p[0],'Enquire about '+p[0])}</div></article>`).join('')}</section><section class="compare"><div class="sectionhead">${eye('At a glance')}<h2>Package <em>comparison.</em></h2></div><div class="tablebox"><table><thead><tr><th>Advertised feature</th>${P.map(p=>`<th>${p[0]}</th>`).join('')}</tr></thead><tbody>${[...new Set(P.flatMap(p=>p[3]))].map(s=>`<tr><th>${s}</th>${P.map(p=>`<td>${p[3].includes(s)?'✓':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">Poster transcription only. Platinum and Ultimate appear similar in the preliminary lists; their differences need owner confirmation.</p></section>${cta()}</main>`}
function gallery(){return `<main>${pageHero('A closer look','Gallery','Browse real photographs of the venue, celebrations, food, animals and outdoor areas. Choose a category or select a photo to view it larger.') }<div class="galleryfilters" role="group" aria-label="Filter gallery photographs">${GC.map(([id,label])=>`<button type="button" data-gallery-filter="${id}" aria-pressed="${id==='all'}">${label}</button>`).join('')}</div><section class="gallery" id="photo-gallery" aria-label="Venue photographs">${G.map((g,i)=>`<button type="button" data-photo="${i}" data-category="${g[3]}" class="gitem g${i}" aria-label="Open photo: ${g[1]}"><img src="${asset('public/images/'+g[0])}" alt="${g[1]}" loading="lazy" decoding="async"><span>${g[2]} <b aria-hidden="true">↗</b></span></button>`).join('')}</section>${cta()}</main>`}
function contact(){let pkg=new URLSearchParams(location.search).get('package')||'';return `<main>${pageHero('We’d love to hear from you','Contact & Bookings','Tell us a little about your celebration. An enquiry is not a confirmed booking.') }<section class="contact"><aside>${eye('Get in touch')}<h2>Let’s talk<br><em>party plans.</em></h2><p>Contact details and party times below are printed on supplied promotional posters. Please confirm them with the owner before publishing or relying on them.</p><a class="contactline" href="tel:0710648880">☎ <span><small>TELEPHONE · VERIFY</small>${B.phone}</span>↗</a><div class="contactline">⌖ <span><small>LOCATION · VERIFY</small>${B.address}</span></div><div class="contactline">◷ <span><small>POSTER TIME SLOTS · VERIFY</small>${B.slots.join(' · ')}</span></div><a class="textlink" href="${B.facebook}" target="_blank" rel="noreferrer">Official Facebook page ↗</a><p class="verify">Poster details awaiting owner confirmation</p></aside><form id="booking">${eye('Party enquiry')}<h2>Tell us what you’re <em>dreaming of.</em></h2><div class="fields"><label>Full name <b>*</b><input required name="name" autocomplete="name" placeholder="Your name"></label><label>Email address <b>*</b><input required type="email" name="email" autocomplete="email" placeholder="you@example.com"></label><label>Contact number <b>*</b><input required type="tel" name="phone" autocomplete="tel" placeholder="Your number"></label><label>Preferred package<select name="package"><option value="">Choose a package</option>${P.map(p=>`<option ${p[0]===pkg?'selected':''}>${p[0]}</option>`).join('')}</select></label><label>Type of celebration<input name="celebration" placeholder="Birthday, special occasion…"></label><label>Preferred date<input name="date" type="date"></label><label>Preferred time slot<select name="time"><option value="">Choose a time</option>${B.slots.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Estimated number of guests <small>(optional)</small><input name="guests" type="number" min="1" placeholder="Optional"></label><label class="full">Additional requirements <small>(optional)</small><textarea name="requirements" rows="4" placeholder="Anything you’d like us to know?"></textarea></label></div><p class="note">This preview form does not send or store your details. Connect a form service before accepting enquiries.</p><button class="button" type="submit">Prepare enquiry →</button><p id="formstatus" role="status"></p></form></section>${cta()}</main>`}
const titles={'/':'Home','/venue':'The Venue','/experiences':'Experiences & Facilities','/packages':'Party Packages','/gallery':'Gallery','/contact':'Contact & Bookings'};
const descriptions={'/':'Explore Sister & Co. Party Venue, advertised party packages and farm-style experiences in Hartzenbergfontein.','/venue':'See the real indoor party room, table arrangements and serving station at Sister & Co. Party Venue.','/experiences':'Explore experiences and facilities advertised by Sister & Co. Party Venue. Confirm availability and package inclusions.','/packages':'Compare the five party packages shown in Sister & Co. promotional posters. Ask the venue to confirm details and pricing.','/gallery':'Browse real photographs of Sister & Co. Party Venue, its decorated room, party setup and outdoor setting.','/contact':'Contact Sister & Co. Party Venue about a party. Enquiry form is a local preview and does not send submissions.'};
function render(){let path=location.pathname.startsWith(SITE_BASE)?'/'+location.pathname.slice(SITE_BASE.length):location.pathname;path=path.replace(/\/$/,'')||'/';let content=({'/':home,'/venue':venue,'/experiences':experiences,'/packages':packages,'/gallery':gallery,'/contact':contact}[path]||home)();document.title=`${titles[path]||titles['/']} | Sister & Co. Party Venue`;document.querySelector('meta[name="description"]').content=descriptions[path]||descriptions['/'];document.querySelector('meta[property="og:title"]').content=document.title;document.querySelector('meta[property="og:description"]').content=descriptions[path]||descriptions['/'];document.querySelector('#app').innerHTML=header()+content+footer();}
function navigate(url){const target=new URL(url,location.href);const targetPath=target.pathname.startsWith(SITE_BASE)?target.pathname:SITE_BASE+target.pathname.replace(/^\//,'');history.pushState({},'',targetPath+target.search+target.hash);render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();navigate(route.getAttribute('href'));return}if(e.target.closest('.menu')){const n=document.querySelector('.header nav');n.classList.toggle('open');e.target.closest('.menu').setAttribute('aria-expanded',n.classList.contains('open'));return}const filter=e.target.closest('[data-gallery-filter]');if(filter){filterGallery(filter);return}const photo=e.target.closest('[data-photo]');if(photo){showLightbox(+photo.dataset.photo)}});
window.addEventListener('popstate',render);
document.addEventListener('submit',e=>{if(e.target.id==='booking'){e.preventDefault();document.querySelector('#formstatus').textContent='This enquiry has not been sent. Connect a form service to receive booking requests.'}});
function filterGallery(button){const category=button.dataset.galleryFilter;document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('#photo-gallery .gitem').forEach(card=>{card.hidden=category!=='all'&&card.dataset.category!==category})}
let activeLightboxClose=null;
function showLightbox(photoIndex){if(activeLightboxClose)activeLightboxClose(false);const visible=[...document.querySelectorAll('#photo-gallery .gitem:not([hidden])')];const indices=visible.length?visible.map(card=>+card.dataset.photo):G.map((_,index)=>index);let position=Math.max(0,indices.indexOf(photoIndex));const opener=document.querySelector(`[data-photo="${photoIndex}"]`);const previousFocus=document.activeElement;const oldOverflow=document.body.style.overflow;const overlay=document.createElement('div');overlay.className='lightbox';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Photo viewer');const paint=()=>{const g=G[indices[position]];overlay.innerHTML=`<button type="button" class="close" aria-label="Close photo viewer">×</button><button type="button" class="prev" aria-label="Previous photo">‹</button><figure><img src="${asset('public/images/'+g[0])}" alt="${g[1]}" decoding="async"><figcaption>${g[2]}</figcaption></figure><button type="button" class="next" aria-label="Next photo">›</button>`};const move=delta=>{position=(position+delta+indices.length)%indices.length;paint()};const key=e=>{if(e.key==='Escape'){e.preventDefault();close();return}if(e.key==='ArrowRight'){e.preventDefault();move(1);return}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);return}if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};const close=(restore=true)=>{overlay.remove();document.body.style.overflow=oldOverflow;document.removeEventListener('keydown',key);activeLightboxClose=null;if(restore){if(opener?.isConnected)opener.focus();else if(previousFocus?.isConnected)previousFocus.focus()}};activeLightboxClose=close;paint();document.body.append(overlay);document.body.style.overflow='hidden';overlay.querySelector('.close').focus();document.addEventListener('keydown',key);overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('.close'))close();else if(e.target.closest('.next'))move(1);else if(e.target.closest('.prev'))move(-1)})}
document.addEventListener('error',e=>{const img=e.target;if(img instanceof HTMLImageElement&&!img.dataset.fallback){img.dataset.fallback='true';img.src=asset('public/image-unavailable.svg');img.classList.add('image-unavailable')}},true);
render();
